const rows = [];
const hashAnswer = value => crypto.createHash("sha256").update(String(value ?? "").normalize("NFKC").trim().replace(/\s+/g, " ").toLowerCase()).digest("hex");
function add(child, tier, difficulty, pool, stem, answer, distractors, feedback, skill, type = "application", extra = {}) {
  const code = CHILDREN[child].code;
  const serial = 1 + rows.filter(row => row.child === child && row.tier === tier).length;
  rows.push({ child, tier, id: `PMOE-${code}-${tier}-${String(serial).padStart(3, "0")}`, q: stem, answer, aHash: hashAnswer(answer), distractors, feedback, primarySkill: skill, type, difficulty, pool, objective: `${code}.${skill}`, ...extra });
}

const TX = "international-transactions-and-identities";
add(TX,"E","easy","easy","Net exports equal which difference?","Exports minus imports",["Imports minus exports","National saving minus consumption","Domestic investment minus national saving"],"Net exports measure domestic sales abroad less domestic purchases of foreign goods and services.","calculate_net_exports","definition");
add(TX,"E","easy","easy","When exports exceed imports, how is the trade balance described?","A trade surplus",["A trade deficit","Balanced trade","A net capital inflow by definition"],"Exports greater than imports make net exports positive, which is a trade surplus.","classify_trade_balance","definition");
add(TX,"E","easy","easy","Which transaction is a U.S. export?","A Canadian household buys software produced by a U.S. firm",["A U.S. household buys a television produced in Korea","A U.S. fund buys bonds issued by Canada","A German firm buys shares issued by a U.S. firm"],"An export is a domestically produced good or service purchased by a foreign buyer.","classify_international_transaction");
add(TX,"E","easy","easy","In the standard open-economy accounts, which identity links trade in goods and services to trade in assets?","NX = NCO",["NX = C + I","NCO = G − T","S = C + NX"],"Net exports equal net capital outflow as an accounting identity.","apply_nx_nco_identity","definition");
add(TX,"E","easy","easy","Positive net capital outflow means that domestic residents' purchases of foreign assets are:","Greater than foreign purchases of domestic assets",["Less than foreign purchases of domestic assets","Equal to domestic investment","Excluded from the international accounts"],"NCO subtracts foreign purchases of domestic assets from domestic purchases of foreign assets.","interpret_nco_sign","definition");
add(TX,"E","easy","easy","Why are imports subtracted in the expenditure approach to GDP?","To remove foreign production already included in C, I, or G",["Because buying imports reduces domestic production by the same amount","To treat imports as domestic intermediate goods","Because imports are transfers rather than purchases"],"Imported spending can first appear in C, I, or G, so subtracting imports prevents foreign production from being counted as domestic output.","explain_import_adjustment");
add(TX,"M","medium","medium","Exports are $720 billion and imports are $810 billion. What is net exports?","−$90 billion",["$90 billion","−$1.53 trillion","$1.53 trillion"],"NX = $720 billion − $810 billion = −$90 billion, a trade deficit.","calculate_net_exports","calculation");
add(TX,"M","medium","medium","An economy has national saving of $640 billion and domestic investment of $500 billion. What is NCO?","$140 billion",["−$140 billion","$500 billion","$1.14 trillion"],"From S = I + NCO, NCO = $640 billion − $500 billion = $140 billion.","calculate_nco_from_saving_investment","calculation");
add(TX,"M","medium","medium","A country records NCO of −$60 billion. What must its net exports equal?","−$60 billion",["$60 billion","$0","An amount that cannot be inferred"],"NX and NCO are equal in the accounts, so negative NCO implies an equal trade deficit.","apply_nx_nco_identity","calculation");
add(TX,"M","medium","medium","Domestic residents buy $240 billion of foreign assets while foreigners buy $310 billion of domestic assets. What is NCO?","−$70 billion",["$70 billion","$240 billion","$550 billion"],"NCO = $240 billion − $310 billion = −$70 billion, indicating net capital inflow.","calculate_nco_transactions","calculation");
add(TX,"M","medium","medium","A household buys a $2,000 imported computer with no other economic change. What does GDP accounting do?","Consumption rises by $2,000 and imports rise by $2,000, leaving GDP unchanged",["GDP falls by $2,000 because imports are subtracted","Investment rises by $2,000 and GDP rises by $2,000","Net exports rise by $2,000 while consumption is unchanged"],"The purchase enters consumption, while the import subtraction removes the foreign-produced computer from domestic GDP.","explain_import_adjustment");
add(TX,"M","medium","medium","If national saving is less than domestic investment, which combination is consistent with the identities?","Negative NCO and a trade deficit",["Positive NCO and a trade surplus","Positive NCO and balanced trade","Zero NCO and a trade deficit"],"S − I equals NCO, so S below I makes NCO negative; NX = NCO makes net exports negative as well.","connect_saving_investment_trade_balance");
add(TX,"H","hard","hard","Output is $2.4 trillion, consumption is $1.5 trillion, investment is $0.4 trillion, and government purchases are $0.6 trillion. What are NX and NCO?","Both are −$0.1 trillion",["Both are $0.1 trillion","NX is −$0.1 trillion and NCO is $0.1 trillion","NX is $0.5 trillion and NCO is −$0.1 trillion"],"NX = Y − C − I − G = 2.4 − 1.5 − 0.4 − 0.6 = −0.1 trillion; NX = NCO.","solve_open_economy_identity","calculation");
add(TX,"H","hard","hard","Private saving is $420 billion, public saving is −$80 billion, and domestic investment is $390 billion. What follows?","National saving is $340 billion, so NCO and NX are −$50 billion",["National saving is $500 billion, so NCO and NX are $110 billion","National saving is $340 billion, so NCO and NX are $50 billion","National saving is −$50 billion, so NCO and NX are −$390 billion"],"National saving is $420 billion − $80 billion = $340 billion. Subtracting $390 billion of investment gives NCO = NX = −$50 billion.","solve_saving_nco_chain","calculation");
add(TX,"H","hard","hard","A student says a trade deficit proves imports destroyed an equal amount of domestic output. Which correction is best?","The deficit records imports above exports; it does not identify the separate response of domestic production",["The claim is correct because imports are subtracted from GDP","A trade deficit means domestic consumption must be falling","The deficit proves national saving exceeds domestic investment"],"Imports are subtracted to exclude foreign production from GDP. The trade balance alone does not show how domestic output changed.","diagnose_import_misconception","diagnosis");
add(TX,"H","hard","hard","Exports rise by $40 billion and imports rise by $65 billion while other GDP components are unchanged. How do NX and GDP change?","Both fall by $25 billion",["Both rise by $105 billion","NX falls by $25 billion while GDP rises by $25 billion","NX rises by $25 billion while GDP is unchanged"],"Net exports change by $40 billion − $65 billion = −$25 billion, so the expenditure identity lowers measured GDP by $25 billion when other components are fixed.","calculate_trade_change","calculation");
add(TX,"H","hard","hard","A country has a $90 billion trade surplus and domestic investment of $260 billion. What national saving is consistent with the accounts?","$350 billion",["$170 billion","$260 billion","$440 billion"],"NX = NCO = $90 billion, and S = I + NCO = $260 billion + $90 billion = $350 billion.","solve_saving_from_trade_balance","calculation");
add(TX,"H","hard","hard","Foreign investors purchase more domestic bonds while domestic purchases of foreign assets are unchanged. What happens initially to NCO and NX?","NCO falls, and NX must be lower in the accounts",["NCO rises, and NX must be higher","NCO is unchanged, while NX falls","NCO falls, while NX must rise"],"More foreign purchases of domestic assets increase the amount subtracted in NCO. Because NX = NCO, the accounting counterpart is lower net exports.","trace_asset_purchase_identity");
add(TX,"EL","elite","elite","Exports and imports both rise, foreign purchases of domestic assets increase, and domestic purchases of foreign assets also increase. Which conclusion is justified without magnitudes?","The signs of NX and NCO are indeterminate, but the two balances must remain equal",["NX must rise because exports increased","NCO must fall because foreign asset purchases increased","NX and NCO can take different values because both sides changed"],"Each balance depends on a difference whose sign requires magnitudes; the accounting identity still requires NX = NCO.","reason_about_indeterminate_balances");
add(TX,"EL","elite","elite","National saving rises by $70 billion, domestic investment rises by $30 billion, exports rise by $55 billion, and imports rise by $15 billion. Are the changes mutually consistent?","Yes; both NCO and NX rise by $40 billion",["No; NCO rises by $100 billion while NX rises by $40 billion","No; NCO falls by $40 billion while NX rises by $70 billion","Yes; both balances rise by $70 billion"],"ΔNCO = ΔS − ΔI = $40 billion, and ΔNX = ΔX − ΔM = $40 billion, so the identities reconcile.","reconcile_open_economy_accounts","calculation");
add(TX,"L","legendary","legendary","Consumption rises by $80 billion entirely through imports, domestic investment rises by $30 billion, and output rises by $30 billion. Government purchases and exports do not change. What happens to NX?","NX falls by $80 billion, exactly offsetting the import-driven rise in consumption",["NX rises by $30 billion because output rises","NX falls by $50 billion because investment also rises","NX is unchanged because domestic output rises"],"The imported consumption raises C and imports by the same $80 billion. With Y and I both rising $30 billion, their effects cancel in Y − C − I − G, leaving NX down $80 billion.","synthesize_gdp_import_accounting","calculation");
add(TX,"L","legendary","legendary","A nation moves from S = $900 billion and I = $960 billion to S = $980 billion and I = $1.00 trillion. How must its external balances change?","NCO and NX rise from −$60 billion to −$20 billion",["NCO and NX fall from −$60 billion to −$100 billion","NCO rises to $20 billion while NX stays at −$60 billion","Both balances become $80 billion"],"Initially S − I = −$60 billion; afterward it is −$20 billion. The trade deficit narrows by $40 billion because NX = NCO.","compare_external_balances","calculation");
add(TX,"L","legendary","legendary","Domestic residents acquire $150 billion more foreign assets while foreigners acquire $90 billion more domestic assets. If the accounts initially balanced, what counterpart is required?","NCO and NX become $60 billion",["NCO and NX become −$60 billion","NCO becomes $240 billion while NX stays zero","NX becomes $90 billion while NCO becomes $150 billion"],"The net change in NCO is $150 billion − $90 billion = $60 billion; NX must match that balance.","reconcile_asset_and_trade_flows","calculation");
add(TX,"L","legendary","legendary","A commentator observes rising imports and concludes that the trade deficit must have widened. What additional information is essential?","The change in exports",["The level of government purchases","The domestic price index alone","The stock of central-bank currency"],"Net exports depend on exports minus imports. Rising imports need not widen the deficit if exports rise by at least as much.","evaluate_trade_balance_claim","diagnosis");
add(TX,"L","legendary","legendary","A government deficit lowers national saving by $50 billion while domestic investment falls by $20 billion. Holding other accounting entries consistent, what happens to NCO and NX?","Both fall by $30 billion",["Both fall by $70 billion","NCO falls by $30 billion while NX rises by $30 billion","Both rise by $20 billion"],"Because NCO = S − I, the change is −$50 billion − (−$20 billion) = −$30 billion; NX changes equally.","trace_saving_investment_external_balance","calculation");
add(TX,"L","legendary","legendary","Two data releases report S − I = $25 billion and exports minus imports = −$10 billion for the same economy and period. What is the best assessment?","The releases cannot both satisfy the standard open-economy identities without a measurement or definition discrepancy",["Both are consistent because saving and trade are unrelated","The figures prove domestic investment equals zero","The figures imply NCO is simultaneously $25 billion and $10 billion"],"S − I, NCO, and NX must be equal when measured consistently, so the conflicting balances require reconciliation.","audit_open_economy_data","diagnosis");
add(TX,"B1","easy","boss","Exports are $500 billion and imports are $620 billion. Which trade balance is correct?","A $120 billion deficit",["A $120 billion surplus","A $1.12 trillion deficit","Balanced trade"],"Exports minus imports equals −$120 billion, so imports exceed exports by $120 billion.","calculate_net_exports","calculation");
add(TX,"B1","easy","boss","Which equation correctly allocates national saving in an open economy?","S = I + NCO",["S = C + G","I = S + NX","NCO = imports − exports"],"National saving finances domestic investment plus net purchases of foreign assets.","apply_saving_identity","definition");
add(TX,"B1","easy","boss","A negative value of NCO describes which situation?","A net capital inflow",["A net capital outflow","A trade surplus","No international asset trade"],"Negative NCO means foreign purchases of domestic assets exceed domestic purchases of foreign assets.","interpret_nco_sign","definition");
add(TX,"B2","medium","boss","National saving is $300 billion and investment is $360 billion. Which external balance follows?","NCO and NX are −$60 billion",["NCO and NX are $60 billion","NCO is −$60 billion and NX is $60 billion","Both balances are $660 billion"],"S − I = −$60 billion, and the identity makes both NCO and NX equal to that amount.","solve_open_economy_identity","calculation");
add(TX,"B2","medium","boss","A domestic airline buys a newly produced aircraft from France. How does the purchase enter domestic GDP accounting?","It raises investment and imports by the same amount",["It lowers investment and raises exports","It enters consumption but not imports","It directly reduces domestic output"],"The aircraft is business investment, but its foreign production is removed through the import term.","classify_imported_investment");
add(TX,"B2","medium","boss","If the trade account is balanced, what must be true of NCO in the same consistent accounts?","NCO equals zero",["NCO is positive","NCO is negative","NCO equals domestic investment"],"Balanced trade means NX = 0, and NX = NCO requires NCO = 0.","apply_nx_nco_identity");
add(TX,"B3","hard","boss","Private saving rises by $40 billion, public saving falls by $15 billion, and investment rises by $10 billion. What is the change in NX?","An increase of $15 billion",["A decrease of $15 billion","An increase of $35 billion","An increase of $65 billion"],"National saving rises by $25 billion. Subtracting the $10 billion investment increase leaves NCO and NX up $15 billion.","solve_saving_nco_chain","calculation");
add(TX,"B3","hard","boss","Imports rise by $70 billion and exports rise by $20 billion, while consumption rises by $70 billion entirely because of the new imports. Other domestic spending is unchanged. What happens to GDP?","GDP rises by $20 billion",["GDP falls by $50 billion","GDP rises by $70 billion","GDP is unchanged"],"The import-driven $70 billion rise in consumption is offset by imports; the $20 billion export increase adds domestic production.","synthesize_gdp_import_accounting","calculation");
add(TX,"B3","hard","boss","A country has positive NCO but a reported trade deficit. Within the same consistently measured period, which statement is correct?","At least one reported balance is inconsistent with the accounting identity",["The combination is expected whenever saving is high","Positive NCO mechanically creates a trade deficit","The signs can differ whenever exchange rates float"],"The identity NX = NCO requires the two balances to share the same value and sign.","audit_open_economy_data","diagnosis");
add(TX,"LB","legendary","legendaryBoss","Output is $5.0 trillion, consumption $3.1 trillion, government purchases $0.9 trillion, and investment $1.2 trillion. Domestic purchases of foreign assets are $260 billion. How much must foreigners purchase in domestic assets?","$460 billion",["$60 billion","$260 billion","$660 billion"],"NX = 5.0 − 3.1 − 0.9 − 1.2 = −$0.2 trillion, so NCO is −$200 billion. With NCO = $260 billion − foreign purchases, foreign purchases equal $460 billion.","solve_full_external_accounts","calculation");
add(TX,"LB","legendary","legendaryBoss","A $100 billion rise in exports accompanies a $130 billion rise in imports. National saving rises by $50 billion. What change in domestic investment preserves all identities?","An increase of $80 billion",["An increase of $20 billion","A decrease of $20 billion","An increase of $180 billion"],"NX falls $30 billion, so NCO falls $30 billion. Since ΔNCO = ΔS − ΔI, −30 = 50 − ΔI, making ΔI = $80 billion.","reconcile_open_economy_accounts","calculation");
add(TX,"LB","legendary","legendaryBoss","An imported machine raises measured investment by $40 million, exports rise by $15 million, and no other expenditure changes. What is the implied GDP change?","An increase of $15 million",["A decrease of $25 million","An increase of $40 million","An increase of $55 million"],"The imported machine adds $40 million to I and subtracts $40 million through imports. Only the $15 million of additional exports raises domestic GDP.","synthesize_gdp_import_accounting","calculation");
add(TX,"R","medium","repairQuestions","A student computes net exports as imports minus exports. Which correction fixes the sign?","Subtract imports from exports",["Add imports to exports","Subtract exports from imports","Use saving plus investment"],"Net exports are X − M, so a larger import value makes NX smaller, not larger.","repair_nx_sign","diagnosis");
add(TX,"BR","hard","bridgeQuestions","National saving exceeds domestic investment. How does that fact connect to the foreign-exchange market?","The positive NCO supplies domestic currency as residents acquire foreign assets",["The saving gap raises demand for domestic currency through imports","Positive NCO removes domestic currency from exchange markets","The saving gap fixes the nominal exchange rate"],"S − I is positive NCO. Residents exchange domestic currency to purchase foreign assets, creating foreign-exchange supply.","bridge_nco_to_fx_supply","bridge");

const NER = "nominal-exchange-rates";
add(NER,"E","easy","easy","An exchange rate of 1.30 euros per dollar means that one dollar can buy:","1.30 euros",["0.30 euro","1 dollar and 30 euros","1.30 dollars"],"The quotation states the foreign-currency amount obtainable for one dollar.","interpret_exchange_rate_quote","definition");
add(NER,"E","easy","easy","If the dollar rises from 0.90 euro per dollar to 0.98 euro per dollar, the dollar has:","Appreciated against the euro",["Depreciated against the euro","Kept the same value","Become the euro's reciprocal"],"One dollar now buys more euros, so the dollar has appreciated.","classify_appreciation_depreciation","definition");
add(NER,"E","easy","easy","When the domestic currency depreciates, its purchasing power over foreign goods generally:","Falls",["Rises","Remains fixed by definition","Becomes equal to domestic inflation"],"A depreciated currency buys fewer units of foreign currency and therefore less foreign output, other things equal.","connect_currency_value_purchasing_power");
add(NER,"E","easy","easy","Which quotation is the reciprocal of 2 dollars per pound?","0.50 pound per dollar",["2 pounds per dollar","1.50 pounds per dollar","0.20 pound per dollar"],"Taking the reciprocal of 2 dollars per pound gives 1/2 pound per dollar.","calculate_reciprocal_rate","calculation");
add(NER,"E","easy","easy","A stronger domestic currency means that one unit of domestic currency buys:","More foreign currency",["Less foreign currency","The same amount of every good","More domestic currency"],"Appreciation raises the foreign-currency value of each unit of domestic currency.","interpret_stronger_currency","definition");
add(NER,"E","easy","easy","A U.S. traveler benefits directly when the dollar appreciates because:","Each dollar buys more foreign currency",["Each foreign-currency unit buys more dollars","U.S. exports become cheaper to foreign buyers","Dollar prices of all U.S. goods must fall"],"A stronger dollar increases the traveler's foreign purchasing power.","apply_appreciation_to_buyers");
add(NER,"M","medium","medium","At 120 yen per dollar, how many yen can $75 purchase?","9,000 yen",["1,600 yen","6,250 yen","14,400 yen"],"Multiply $75 by 120 yen per dollar to obtain 9,000 yen.","convert_currency","calculation");
add(NER,"M","medium","medium","The rate changes from 1.25 Canadian dollars per U.S. dollar to 1.20. What happened to the U.S. dollar?","It depreciated against the Canadian dollar",["It appreciated against the Canadian dollar","It appreciated by 5 percent","It remained unchanged in reciprocal terms"],"One U.S. dollar buys fewer Canadian dollars, so it depreciated.","classify_appreciation_depreciation");
add(NER,"M","medium","medium","A hotel costs 240 euros. At 0.80 euro per dollar, what is its dollar price?","$300",["$192","$240","$320"],"Divide 240 euros by 0.80 euro per dollar: the hotel costs $300.","convert_foreign_price","calculation");
add(NER,"M","medium","medium","The dollar appreciates against the peso. Holding product prices fixed in their own currencies, which buyer gains purchasing power?","A U.S. buyer purchasing Mexican goods",["A Mexican buyer purchasing U.S. goods","A U.S. exporter paid only in dollars","Both buyers gain the same foreign purchasing power"],"A stronger dollar buys more pesos, making peso-priced goods cheaper in dollar terms.","apply_appreciation_to_buyers");
add(NER,"M","medium","medium","If 1 euro buys $1.25, approximately how many euros does $1 buy?","0.80 euro",["1.25 euros","0.25 euro","2.25 euros"],"The reciprocal of 1.25 dollars per euro is 0.80 euro per dollar.","calculate_reciprocal_rate","calculation");
add(NER,"M","medium","medium","The exchange rate rises from 100 to 110 pesos per dollar. By what percentage does the dollar appreciate under this quotation?","10 percent",["9.1 percent","11 percent","110 percent"],"The dollar's value rises by 10 pesos on a base of 100, so the appreciation is 10 percent.","calculate_currency_percentage_change","calculation");
add(NER,"H","hard","hard","The rate moves from $1.20 per euro to $1.32 per euro. Which statement is correct?","The euro appreciates 10 percent against the dollar",["The dollar appreciates 10 percent against the euro","The euro depreciates about 9.1 percent","The reciprocal rate also rises 10 percent"],"The dollar price of one euro rises by $0.12 on a $1.20 base, so the euro appreciates 10 percent.","calculate_currency_percentage_change","calculation");
