const expectedTierCounts = Object.freeze({ E: 6, M: 6, H: 6, EL: 2, L: 6, B1: 3, B2: 3, B3: 3, LB: 3, R: 1, BR: 1 });
for (const child of Object.keys(CHILDREN)) {
  const childRows = rows.filter(row => row.child === child);
  if (childRows.length !== 40) throw new Error(`${child} has ${childRows.length}/40 authored questions.`);
  for (const [tier, expected] of Object.entries(expectedTierCounts)) {
    const actual = childRows.filter(row => row.tier === tier).length;
    if (actual !== expected) throw new Error(`${child} ${tier} has ${actual}/${expected}.`);
  }
}
if (new Set(rows.map(row => row.id)).size !== rows.length) throw new Error("Duplicate open-economy IDs.");
if (new Set(rows.map(row => row.q.toLowerCase())).size !== rows.length) throw new Error("Duplicate open-economy stems.");
for (const row of rows) {
  if (row.distractors.length !== 3) throw new Error(`${row.id} does not have three distractors.`);
  if (new Set([row.answer, ...row.distractors].map(value => value.normalize("NFKC").trim().toLowerCase())).size !== 4) throw new Error(`${row.id} has duplicate options.`);
  if (!row.feedback || !row.primarySkill || !row.type || !row.objective) throw new Error(`${row.id} lacks required metadata.`);
  if (row.asset && !GRAPH_ASSETS[row.asset]) throw new Error(`${row.id} references unknown graph ${row.asset}.`);
}

export const productionQuestions = Object.freeze(rows.map(row => Object.freeze(row)));
export const authorQualityAudit = auditAuthoredQuestions(productionQuestions, { conceptId: FAMILY_ID, validateAssets: false });
if (authorQualityAudit.counts.errors) {
  const errors = authorQualityAudit.findings.filter(finding => finding.severity === "ERROR").map(finding => `${finding.questionId}:${finding.rule}`);
  throw new Error(`Open-economy authoring quality gate failed: ${errors.join(", ")}`);
}
